export function formatMessage(
  template: string,
  values: Record<string, string | number>,
) {
  return template.replace(/\{([A-Za-z0-9_]+)\}/g, (match, key) =>
    key in values ? String(values[key]) : match,
  );
}
export function formatDate(value: string, locale: Locale) { const date = new Date(value); return Number.isNaN(date.getTime()) ? value : new Intl.DateTimeFormat(locale, {dateStyle:"medium",timeStyle:"short"}).format(date); }
