export function navigationLabel(pathname: string, fallback: string, locale: Locale) {
  if (pathname === "/tasks") {
    if (locale === "en") return fallback;
    return fallback === "All Tasks" ? "งานทั้งหมด" : "งานของฉัน";
  }
  return navigationLabels[locale][pathname] ?? fallback;
}

export function sidebarConnectionLabel(
  loading: boolean,
  online: boolean,
  locale: Locale,
) {
  if (loading) return locale === "th" ? "กำลังเชื่อมต่อ…" : "Connecting…";
  if (online) return locale === "th" ? "FastAPI เชื่อมต่อแล้ว" : "FastAPI Connected";
  return locale === "th" ? "Backend ออฟไลน์" : "Backend Offline";
}

